// সুন্নাহর পথে — offline service worker (generated by build.py)
const CACHE = "sunnah-0e58b0f962";
const ASSETS = ['./', 'index.html', 'fonts.css', 'manifest.webmanifest', 'fonts/Amiri-400-arabic.woff2', 'fonts/Amiri-400-latin.woff2', 'fonts/HindSiliguri-400-bengali.woff2', 'fonts/HindSiliguri-400-latin.woff2', 'fonts/HindSiliguri-600-bengali.woff2', 'fonts/HindSiliguri-600-latin.woff2', 'fonts/TiroBangla-400-bengali.woff2', 'fonts/TiroBangla-400-latin.woff2', 'icons/apple-touch-icon.png', 'icons/icon-192.png', 'icons/icon-512.png', 'icons/maskable-512.png'];

self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});
self.addEventListener("activate", e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener("fetch", e => {
  const req = e.request;
  if (req.method !== "GET" || new URL(req.url).origin !== location.origin) return;
  e.respondWith(caches.open(CACHE).then(async cache => {
    const hit = await cache.match(req, {ignoreSearch: true}) || (req.mode === "navigate" ? await cache.match("index.html") : null);
    const net = fetch(req).then(res => { if (res.ok) cache.put(req, res.clone()); return res }).catch(() => hit);
    return hit || net;
  }));
});
